226:  * @param theme 要应用的内置ribbon主题
227:  * @param palette 用于QSS模板中标记替换的调色板
228:  * \endif
229:  */
230: void applyRibbonTheme(QWidget* w, SARibbonBar* bar, SARibbonTheme theme,
231:                       const SARibbonThemePalette& palette)
232: {
233:     // If palette is provided and a template exists, use template-based approach
234:     QString templatePath = themeToTemplatePath(theme);
235:     if (palette.variables().size() > 0 && !templatePath.isEmpty() && w) {
236:         QFile baseFile(":/SARibbonTheme/resource/theme-base.qss");
237:         QString baseQss;
238:         if (baseFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
239:             baseQss = QString::fromUtf8(baseFile.readAll());
240:         }
241: 
242:         // Load the QSS template
243:         QFile templateFile(templatePath);
244:         if (templateFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
245:             QString templateQss = QString::fromUtf8(templateFile.readAll());
246:             // Replace {{token}} placeholders with palette colors
247:             QString processedQss = SA::replaceQssTokens(templateQss, palette);
248:             w->setStyleSheet(baseQss + "\n" + processedQss);
249:         } else {
250:             // Template file not found, fall back to base QSS
251:             qWarning() << "applyRibbonTheme: template not found:" << templatePath
252:                        << "- falling back to base QSS";
253:             QFile baseOnly(":/SARibbonTheme/resource/theme-base.qss");
254:             if (baseOnly.open(QIODevice::ReadOnly | QIODevice::Text)) {
255:                 w->setStyleSheet(QString::fromUtf8(baseOnly.readAll()));
256:             }
257:         }
258:     } else if (w) {
259:         // Empty palette — fall back to base QSS only
260:         QFile baseQss(":/SARibbonTheme/resource/theme-base.qss");
261:         if (baseQss.open(QIODevice::ReadOnly | QIODevice::Text)) {
262:             w->setStyleSheet(QString::fromUtf8(baseQss.readAll()));
263:         }
264:     }
